  time_left = data.start*1000 - parseInt(+new Date);

  for (let snail_data of data.snails) {
    let worker = new Worker('/static/snail.js');
    let snail = {
      id: snail_id,
      name: undefined,
      color_name: snail_data.color,
      color: snail_data.color.replaceAll(' ',''),
      position: 0,
      custom: snail_data.custom,
      x:0,
      worker: worker
    };
