  }

  if (data.bet) {
    document.getElementById('status').innerText =
      `Bet $${data.bet} on Snail ${['A','B'][data.side]}`
  } else if (left < 0) {
    document.getElementById('status').innerText = `Betting closed`
  } else {
    document.getElementById('status').innerText = ``
  }

  if (left > 2) {
    if (!is_betting && !data.bet)
      start_betting()

    clearTimeout(to);
